input.script:
interface Verdict {
  /** 这一项是否通过核验。 */
  ok: boolean;
}
// 一个检查员失败不拖垮整个阶段：失败折成一句话，其余结论照常汇合。
async function settle<T>(work: PromiseLike<T>): Promise<T | string> {
  try {
    return await work;
  } catch {
    return "未通过";
  }
}
const items = channel<string>("条目");
phase("铺开");
const checks = await Promise.all([
  settle(agent("检查员一").ask("E2E_DWV_TASK_1 核对第一项，给出一句结论。")),
  settle(agent("检查员二").ask("E2E_DWV_TASK_2 核对第二项，给出一句结论。")),
  settle(agent("检查员三").ask("E2E_DWV_TASK_3 核对第三项，给出一句结论。")),
  settle(agent("检查员四").ask<Verdict>("E2E_DWV_FAIL_4 核验第四项并提交结果。")),
  settle(agent("检查员五").ask<Verdict>("E2E_DWV_FAIL_5 核验第五项并提交结果。")),
  settle(agent("检查员六").ask<Verdict>("E2E_DWV_FAIL_6 核验第六项并提交结果。")),
  settle(agent("检查员七").ask<Verdict>("E2E_DWV_FAIL_7 核验第七项并提交结果。")),
  settle(agent("检查员八").ask<Verdict>("E2E_DWV_FAIL_8 核验第八项并提交结果。")),
  settle(agent("检查员九").ask<Verdict>("E2E_DWV_FAIL_9 核验第九项并提交结果。")),
]);
// 两段流水：产出边找边送，消化边收边读；两段都先启动，再一次性汇合。
const produce = future(async () => {
  phase("产出");
  const producer = agent("产出员");
  try {
    items.send(await producer.ask("E2E_DWV_TASK_PRODUCE_1 产出第一条条目。"));
    items.send(await producer.ask("E2E_DWV_TASK_PRODUCE_2 产出第二条条目。"));
  } finally {
    items.close();
  }
});
const digest = future(async () => {
  phase("消化");
  const reader = agent("消化员");
  const notes: string[] = [];
  for await (const item of items) {
    notes.push(await reader.ask(`E2E_DWV_TASK_DIGEST 消化这条条目：${item}`));
  }
  return notes;
});
const [, notes] = await Promise.all([produce, digest]);
let draft = notes.join("；");
for (let round = 1; round <= 2; round++) {
  phase("起草");
  draft = await agent(`起草员${round}`).ask(`E2E_DWV_TASK_DRAFT_${round} 按材料起草：${draft}`);
  phase("复核");
  await agent(`复核员${round}`).ask(`E2E_DWV_TASK_REVIEW_${round} 复核这一稿：${draft}`);
}
phase("收尾");
const final = await agent("收尾员").ask(`E2E_DWV_TASK_FINAL 定稿：${draft}`);
return { final, checks };
